'use strict';
const LifeReel=(()=>{
 const cap=20,copy=x=>JSON.parse(JSON.stringify(x)),clean=(x,n)=>String(x||'').replace(/\s+/g,' ').trim().slice(0,n);
 function stage(s,age){const b=Engine.ageEquivalent(age,s.race);return b<4?'early':b<12?'child':b<18?'teen':b<40?'adult':b<60?'middle':'elder'}
 function weight(e){return e.key==='birth'||e.key==='life-end'?100:e.kind==='growth'?95:e.kind==='loss'?88:e.choice&&/human-path|project|love|family|society|office|faith|housing/.test(e.key||'')?86:e.choice?65:e.kind==='spending'&&e.key?.startsWith('housing-')?82:0}
 function page(e){return {key:clean(e.key||'page-'+e.id,160),title:clean(e.title,290),paragraphs:[clean(e.paragraphs?.[0]||e.summary,380)],choice:clean(e.choice,180),age:e.age||0,month:e.month||1,realm:e.realm,kind:e.kind||'memory',tone:e.tone||'neutral',scene:e.scene,weight:weight(e),...(VisualMemory.has(e)?{visual:copy(e.visual)}:{})}}
 function observe(s,e){const w=weight(e);if(!w)return;if(!s.lifeReel)s.lifeReel={version:1,frames:[]};const a=s.lifeReel.frames,p=page(e),prior=a.findIndex(x=>x.key===p.key);if(prior>=0)return;a.push(p);if(a.length>cap){let drop=-1;const unique=x=>a.filter(y=>stage(s,y.age)===stage(s,x.age)&&y.kind==='growth').length===1;for(let i=0;i<a.length;i++){const x=a[i];if(x.key==='birth'||x.key==='life-end'||x.kind==='growth'&&unique(x))continue;if(drop<0||x.weight<a[drop].weight||x.weight===a[drop].weight&&i<drop)drop=i}a.splice(drop<0?1:drop,1)}}
 function records(s){const byKey=new Map,put=e=>byKey.set(e.key+'@'+e.age+':'+e.month+':'+e.choice,e);for(const e of s.lifeLegacy?.entries||[])if(!e.legacyAgeMismatch&&!e.legacyEcologyMismatch)put(page(e));for(const e of [...(s.diary?.entries||[])].reverse())if(!e.legacyAgeMismatch&&!e.legacyEcologyMismatch)put(page(e));for(const e of s.lifeReel?.frames||[])put(copy(e));return [...byKey.values()].filter(e=>e.age<=s.age).sort((a,b)=>a.age-b.age||a.month-b.month)}
 function slides(s){const all=records(s),chosen=new Map,add=e=>{if(e)chosen.set(e.key,e)};add(all.find(e=>e.key==='birth'));for(const k of ['early','child','teen','adult','middle','elder'])add(all.find(e=>e.kind==='growth'&&stage(s,e.age)===k));for(const e of all.filter(e=>e.choice||e.kind==='loss'||e.key.startsWith('housing-')).sort((a,b)=>b.weight-a.weight).slice(0,9))add(e);if(!chosen.size&&all.length)add(all[0]);const list=[...chosen.values()].filter(e=>e.key!=='life-end').sort((a,b)=>a.age-b.age||a.month-b.month).slice(0,16);const r=LifeLegacy.summary(s);if(r.people.length||r.departed.length)list.push({key:'reel-people',title:'คนที่มีความหมายในชีวิตนี้',paragraphs:[...r.people,...r.departed].slice(0,3).map(p=>p.name+' · '+clean(p.text,110)),age:s.age,month:1,realm:s.kingdom,kind:'memory'});const death=all.find(e=>e.key==='life-end');list.push(death?{...death,paragraphs:[s.cause||death.paragraphs[0]]}:{key:'reel-farewell',title:'หน้าสุดท้ายของ '+s.name,paragraphs:[s.cause||'ชีวิตนี้ถูกเก็บไว้ในบันทึกแล้ว'],age:s.age,month:1,realm:s.kingdom,kind:'loss'});return list}
 function valid(s){const r=s.lifeReel;if(r===undefined)return true;return r&&r.version===1&&Array.isArray(r.frames)&&r.frames.length<=cap&&new Set(r.frames.map(x=>x.key)).size===r.frames.length&&r.frames.every(e=>e&&typeof e.key==='string'&&e.key.length<=160&&typeof e.title==='string'&&e.title.length<=290&&Array.isArray(e.paragraphs)&&e.paragraphs.length===1&&typeof e.paragraphs[0]==='string'&&e.paragraphs[0].length<=380&&typeof e.choice==='string'&&e.choice.length<=180&&Number.isFinite(e.age)&&e.age>=0&&e.age<=s.age&&Number.isInteger(e.month)&&e.month>=1&&e.month<=12&&Number.isInteger(e.realm)&&e.realm>=0&&e.realm<KINGDOMS.length&&Number.isInteger(e.weight)&&e.weight>=0&&e.weight<=100&&(e.scene===undefined||typeof e.scene==='string'&&e.scene.length<100)&&(e.tone===undefined||typeof e.tone==='string'&&e.tone.length<40)&&typeof e.kind==='string'&&e.kind.length<40&&(e.visual===undefined||VisualMemory.validFrame(e.visual)))}
 return {observe,records,slides,valid,stage,cap};
})();
